-- PRIVATE typed data proposal; no gameplay JSON rule publication.
-- Apply only with schema348 and the matching reviewed scene implementation.
DO $scene_seed$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('native_scene_policy:'||'wakemu.mineral_tower_186.native_start.v1',0));
    IF EXISTS (SELECT 1 FROM native_scene_policies WHERE policy_id='wakemu.mineral_tower_186.native_start.v1') THEN
        IF NOT EXISTS (SELECT 1 FROM native_scene_policies WHERE policy_id='wakemu.mineral_tower_186.native_start.v1' AND policy_sha256='c27ca2faf35b8eed03d321790706a5861ed49e05ab7f4a7676a86876c2e7dcd9' AND published) THEN
            RAISE EXCEPTION 'Existing native scene identity differs from reviewed immutable seed';
        END IF;
        RETURN;
    END IF;
    UPDATE native_scene_policies SET published=true WHERE policy_id='wakemu.mineral_tower_186.native_start.v1';
END $scene_seed$;
